-- Validate OpenAQ freshness after refresh

SET NOCOUNT ON;

-- Silver must contain data
IF NOT EXISTS (
    SELECT 1
    FROM lh_nyc_taxi.dbo.silver_openaq_daily
)
    THROW 50020, 'Silver OpenAQ is empty', 1;

-- Silver data must not be older than 3 days
IF (
    SELECT MAX(measurement_date)
    FROM lh_nyc_taxi.dbo.silver_openaq_daily
) < DATEADD(DAY, -3, CAST(GETDATE() AS DATE))
    THROW 50021, 'Silver OpenAQ data is stale', 1;

-- Gold must contain data
IF NOT EXISTS (
    SELECT 1
    FROM dbo.FactAirQualityDaily
)
    THROW 50022, 'Gold OpenAQ is empty', 1;

-- Gold must include the latest Silver date
IF (
    SELECT MAX(measurement_date)
    FROM dbo.FactAirQualityDaily
) < (
    SELECT MAX(measurement_date)
    FROM lh_nyc_taxi.dbo.silver_openaq_daily
)
    THROW 50023, 'Gold OpenAQ is behind Silver', 1;
